std::string action(const ManualProcedureGraph& task){return f(task.learnerActions().array().front(),"action").string();}
void positive(ManualProcedureGraph& task){task.apply(task.capture(action(task)),positiveFor(task));}
void at(ManualProcedureGraph& task,const std::string& node){for(int i=0;i<160;++i){const auto v=task.learnerView();if(f(v,"state")==V("active")&&v.find("node")&&f(v,"node")==V(node))return;check(f(v,"state")!=V("needs_retry")&&f(v,"state")!=V("completed"),"MATERIAL_PATH");positive(task);}check(false,"MATERIAL_LOOP");}
void released(ManualProcedureGraph& task){if(f(task.learnerView(),"needs_manual_release")==V(true))positive(task);}
void finishPositive(ManualProcedureGraph& task){for(int i=0;i<160&&f(task.learnerView(),"state")!=V("completed");++i){check(f(task.learnerView(),"state")!=V("needs_retry"),"RECOVERY_DIAG");positive(task);}check(f(task.learnerView(),"state")==V("completed"),"RECOVERY_COMPLETED");}
